    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); D=np.array(G['Demo pair 1 input']); out=np.array(G['Demo pair 1 output'])
D2=np.array(G['Demo pair 2 input']); out2=np.array(G['Demo pair 2 output'])
def cell_objs(g):
    H,W=g.shape; seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); obj=[]
                while q:
                    rr,cc=q.pop(); obj.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(rr+dr,cc+dc)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]] and n not in seen:
                            seen.add(n); q.append(n)
                res.append(obj)
    return res
def solve(Di):
    g=np.array(Di)
    objs=cell_objs(g)
    T=max(objs,key=len)
    R=[o for o in objs if o is not T][0]
    rsT=[p[0] for p in T]; csT=[p[1] for p in T]
    rsR=[p[0] for p in R]; csR=[p[1] for p in R]
    th=min(rsT); tw=min(csT)
    hT=max(rsT)-th+1; wT=max(csT)-tw+1
    thR=min(rsR); twR=min(csR)
    hR=max(rsR)-thR+1; wR=max(csR)-twR+1
    TT=g[th:th+hT,tw:tw+wT]
    RR=g[thR:thR+hR,twR:twR+wR]
    mT=(TT!=0); mR=(RR!=0)
    best=(-1,None,None)
    for dr in range(-(hR-1),hT):
        for dc in range(-(wR-1),wT):
            bad=0
            for i in range(hT):
                for j in range(wT):
                    ii,jj=i+dr,j+dc
                    if 0<=ii<hR and 0<=jj<wR:
                        if mT[i][j]!=mR[ii][jj]: bad+=1
            if bad<best[0]: best=(bad,dr,dc)
    dr,dc=best[1],best[2]
    hh,ww=hT,wT
    res=[[0]*ww for _ in range(hh)]
    for r in range(hh):
        for c in range(ww):
            mr=0<=r+dr<hR and 0<=c+dc<wR
            if mr:
                res[r][c]=8 if mT[r][c]!=mR[r+dr][c+dc] else 0
    return res
for name,(Di,Go) in (('Demo pair 1',(D,out.tolist())),('Demo pair 2',(D2,out2.tolist()))):
    pred=solve(Di)
    print(name,pred==Go)

